 ch.push(new Chart($('c1'),{type:'bar',data:{labels:nm,datasets:[{label:'SPK',data:ag.map(a=>a[2]),backgroundColor:hd,borderRadius:6},{label:'Target',data:ag.map(a=>a[3]),backgroundColor:ln,borderRadius:6}]},options:o}));
 ch.push(new Chart($('c2'),{type:'bar',data:{labels:nm,datasets:[{label:'DO DMS',data:ag.map(a=>a[6]),backgroundColor:ac,borderRadius:6},{label:'Target DO',data:ag.map(a=>a[8]),backgroundColor:ln,borderRadius:6}]},options:o}));
 const pal=['#c8102e','#6b7280','#e8707f','#9ca3af','#8b0f22','#d1d5db','#4b5563','#f3b3bb'];
