 const bn=Object.keys(BR),PF=['PERORANGAN','PERUSAHAAN','GSO','FLEET'],ix=k=>{const j=PF.findIndex(p=>k.toUpperCase().startsWith(p));return j<0?99:j};
 const ks=Object.keys(JP).sort((a,b)=>ix(a)-ix(b)||a.localeCompare(b)),v=(k,b)=>(JP[k]&&JP[k][b]||[0,0])[i];
 const bt=bn.map(b=>ks.reduce((a,k)=>a+v(k,b),0)),G=bt.reduce((a,x)=>a+x,0);
