 ks.forEach((k,n)=>{let t=0;h+=`<tr><td>${n+1}</td><td class=l>${k}</td>`;bn.forEach((b,j)=>{t+=v(k,b);h+=`<td>${v(k,b)}</td>${pb(v(k,b),bt[j])}`});h+=`<td class=n>${t}</td>${pb(t,G)}</tr>`});
