 const tv=a=>a.slice(0,6).reduce((x,y)=>x+y,0),tt=a=>a.reduce((x,y)=>x+y,0),add=(a,b)=>a.map((v,i)=>v+b[i]);
 const cell=(a,z)=>a.map(v=>'<td>'+(v||(z?'0':'-'))+'</td>').join(''),pc=(a,t)=>a.map(v=>'<td>'+(t?Math.round(v/t*100):0)+'%</td>').join('');
