 const grp=a=>{const g=a[0]?a[2]/a[0]-1:NaN;return`<td>${Z(a[0])}</td><td>${Z(a[1])}</td><td>${Z(a[2])}</td><td class="${isFinite(g)?(g>=0?'g':'r'):''}">${isFinite(g)?(g*100).toFixed(2)+'%':'-'}</td>`};
 const rg=(no,l,f)=>`<tr><td>${no}</td><td class=l>${l}</td>${bs.map(b=>grp(f(b))).join('')}${grp(sumA(f))}</tr>`;
